"""LaTeX tables generated from the comparison table, never typed by hand."""
from __future__ import annotations

import pandas as pd

HEADER = (
    "% Generated by scripts/07_export_report_assets.py from outputs/tables/comparison_table.csv.\n"
    "% Do not edit by hand; rerun the script (it has a --check mode).\n"
)

_COLUMN_LABELS = {"status_quo": "Status Quo", "seattle": "Seattle Rule", "full_pbd": "Full PBD"}


def column_label(col: str) -> str:
    """`seattle_phase_a` -> `Seattle Rule (phase a)`; a cycling scenario has one column per phase."""
    base, sep, phase = col.partition("_phase_")
    label = _COLUMN_LABELS.get(base, base.replace("_", " ").title())
    return f"{label} (phase {phase})" if sep else label


def _usd(v: float) -> str:
    return f"\\${v:,.0f}".replace(",", "\\,")


def _usd_m(v: float) -> str:
    return f"\\${v / 1e6:,.2f}\\,M"


def _rate(v: float) -> str:
    return f"\\${v:,.2f}/hr"


# (row label, comparison-table row, formatter)
ROWS = (
    ("Annual meter revenue", "total_revenue", _usd_m),
    ("Revenue to neighborhoods (PBD)", "pbd_revenue", _usd_m),
    ("PBD share not payable after the General Fund minimum", "pbd_unfunded", _usd_m),
    ("Revenue to school district", "sdp_revenue", _usd_m),
    ("Revenue to general fund", "gf_to_general_fund", _usd_m),
    ("Mean meter rate --- CCC", "mean_price_ccc", _rate),
    ("Mean meter rate --- CCA", "mean_price_cca", _rate),
    ("Annual cruising DWL", "cruising_dwl_total", _usd),
    ("Consumer surplus change (annual, first order)", "cs_change_total", _usd_m),
)


def scenario_comparison_tex(table: pd.DataFrame) -> str:
    """`tabularx` for the white paper's scenario table, one column per comparison-table column.

    Values are at the model's own scale (no multiplier): whatever segment set produced the
    saved scenarios is the scale of the table.
    """
    cols = list(table.columns)
    lines = [
        HEADER + "\\begin{tabularx}{\\linewidth}{l" + "X" * len(cols) + "}",
        "\\toprule",
        "\\textbf{Metric} & " + " & ".join(f"\\textbf{{{column_label(c)}}}" for c in cols) + " \\\\",
        "\\midrule",
    ]
    for label, key, fmt in ROWS:
        cells = " & ".join(fmt(float(table.loc[key, c])) for c in cols)
        lines.append(f"{label} & {cells} \\\\")
    lines += ["\\bottomrule", "\\end{tabularx}", ""]
    return "\n".join(lines)
